effect.shader:
void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    vec2 p = acScreenNorm - source;
    p.x *= acAspect;
    float r = length(p);
    float onda = fract((r - acTime * speed) / spacing);
    float dist = min(onda, 1.0 - onda);
    float anel = smoothstep(width, 0.0, dist);
    float decai = exp(-r * 1.5);
    vec3 cor = orig.rgb + tint.rgb * tint.a * anel * intensity * decai;
    fragColor = vec4(cor, orig.a);
}
